static void lvgl_app_assets_log_font_glyph(const char *font_name,
                                           const lv_font_t *font,
                                           uint32_t codepoint,
                                           const char *label)
{
  lv_font_glyph_dsc_t dsc;
  bool ok;

  if (font == NULL)
    {
      LVGL_APP_LOGW(ASSETS_TAG,
                    "font glyph probe skipped font=%s cp=U+%04lx label=%s",
                    font_name, (unsigned long)codepoint,
                    label != NULL ? label : "");
      return;
    }

  ok = lv_font_get_glyph_dsc(font, &dsc, codepoint, 0);
  LVGL_APP_LOGI(ASSETS_TAG,
                "font glyph font=%s ptr=%p cp=U+%04lx label=%s ok=%d placeholder=%u resolved=%p adv=%u box=%ux%u",
                font_name,
                font,
                (unsigned long)codepoint,
                label != NULL ? label : "",
                ok ? 1 : 0,
                (unsigned int)dsc.is_placeholder,
                dsc.resolved_font,
                (unsigned int)dsc.adv_w,
                (unsigned int)dsc.box_w,
                (unsigned int)dsc.box_h);
}

static void lvgl_app_assets_log_default_font(const lv_font_t *font,
                                             const char *font_name,
                                             int ret)
{
  if (font == NULL)
    {
      LVGL_APP_LOGW(ASSETS_TAG,
                    "default font not registered ret=%d name=%s default=%p",
                    ret, font_name, lv_font_default());
      return;
    }

  LVGL_APP_LOGI(ASSETS_TAG,
                "default font registered ret=%d name=%s ptr=%p default=%p line_height=%ld base_line=%ld fallback=%p",
                ret,
                font_name,
                font,
                lv_font_default(),
                (long)font->line_height,
                (long)font->base_line,
                font->fallback);

  lvgl_app_assets_log_font_glyph(font_name, font, 0x5df2, "已");
  lvgl_app_assets_log_font_glyph(font_name, font, 0x9009, "选");
  lvgl_app_assets_log_font_glyph(font_name, font, 0x4e2d, "中");
  lvgl_app_assets_log_font_glyph(font_name, font, 0x65e5, "日");
  lvgl_app_assets_log_font_glyph(font_name, font, 0x5fd7, "志");
  lvgl_app_assets_log_font_glyph(font_name, font, 0x89e6, "触");
  lvgl_app_assets_log_font_glyph(font_name, font, 0x6478, "摸");
  lvgl_app_assets_log_font_glyph(font_name, font, 0x53cd, "反");
  lvgl_app_assets_log_font_glyph(font_name, font, 0x9988, "馈");
}

