static int gt911_control(FAR struct touch_lowerhalf_s *lower, int cmd,
                         unsigned long arg) {
  int ret = -ENOTTY;

  switch (cmd) {
  case TSIOC_GETMAXPOINTS: {
    FAR uint8_t *maxpoint = (FAR uint8_t *)((uintptr_t)arg);
    if (maxpoint) {
      *maxpoint = 1; /* Current driver implementation supports 1 point */
      ret = OK;
    } else {
      ret = -EINVAL;
    }
  } break;

  default:
    break;
  }

  return ret;
}

