{
    int primary_index = -1;

    for(int i = 0; i < sample->npoints; i++) {
        uint8_t touch_flags = sample->point[i].flags;

        if(touchscreen->primary_point.id == sample->point[i].id) {
            if(touch_flags & (TOUCH_DOWN | TOUCH_MOVE)) {
