/****************************************************************************
 * Name: touch_poll
 ****************************************************************************/

static int touch_poll(FAR struct file *filep, FAR struct pollfd *fds,
                      bool setup)
{
  FAR struct touch_openpriv_s *openpriv = filep->f_priv;
  pollevent_t eventset = 0;
  irqstate_t flags;
  int ret = OK;

  flags = spin_lock_irqsave_nopreempt(&openpriv->lock);

  if (setup)
    {
      if (openpriv->fds == NULL)
        {
          openpriv->fds = fds;
          fds->priv     = &openpriv->fds;
        }
      else
        {
          ret = -EBUSY;
          goto errout;
        }

      if (!circbuf_is_empty(&openpriv->circbuf))
        {
          eventset |= POLLIN;
        }

      poll_notify(&fds, 1, eventset);
    }
  else if (fds->priv)
    {
      openpriv->fds = NULL;
      fds->priv     = NULL;
    }

errout:
  spin_unlock_irqrestore_nopreempt(&openpriv->lock, flags);
  return ret;
}

