static void dash_update_selection_box(lvgl_app_page_home_view_t *view,
                                      lv_obj_t *target)
{
  int32_t x;
  int32_t y;
  int32_t w;
  int32_t h;

  if (view == NULL || view->selection_box == NULL)
    {
      return;
    }

  if (target == NULL)
    {
      lv_obj_add_flag(view->selection_box, LV_OBJ_FLAG_HIDDEN);
      LVGL_APP_LOGI(HOME_VIEW_TAG, "selection box hide");
      return;
    }

  x = lv_obj_get_x(target);
  y = lv_obj_get_y(target);
  w = lv_obj_get_width(target);
  h = lv_obj_get_height(target);

  lv_obj_set_pos(view->selection_box, x - 3, y - 3);
  lv_obj_set_size(view->selection_box, w + 6, h + 6);
  lv_obj_remove_flag(view->selection_box, LV_OBJ_FLAG_HIDDEN);
  lv_obj_move_foreground(view->selection_box);

  LVGL_APP_LOGI(HOME_VIEW_TAG,
                "selection box show target=%p box=%p pos=%ld,%ld size=%ldx%ld",
                target,
                view->selection_box,
                (long)(x - 3),
                (long)(y - 3),
                (long)(w + 6),
                (long)(h + 6));
}

static int dash_left_card_index(lvgl_app_home_component_id_t component)
{
  switch (component)
    {
      case LVGL_APP_HOME_COMPONENT_MIC:
        return 0;

      case LVGL_APP_HOME_COMPONENT_WIFI:
        return 1;

      case LVGL_APP_HOME_COMPONENT_BLUETOOTH:
        return 2;

      case LVGL_APP_HOME_COMPONENT_DISPLAY:
        return 3;

      case LVGL_APP_HOME_COMPONENT_KEY_READY:
        return 4;

      case LVGL_APP_HOME_COMPONENT_SD_CARD:
        return 5;

      default:
        return -1;
    }
}

static void dash_update_left_card_feedback(lvgl_app_page_home_view_t *view,
                                           lvgl_app_home_component_id_t component)
{
  int selected;

  if (view == NULL)
    {
      return;
    }

  selected = dash_left_card_index(component);
  for (unsigned int i = 0; i < LVGL_APP_HOME_LEFT_CARD_COUNT; i++)
    {
      lv_obj_t *card = view->left_card_images[i];

      if (card == NULL)
        {
          continue;
        }

      lv_img_set_zoom(card,
                      (selected >= 0 && (unsigned int)selected == i) ?
                      DASH_LEFT_CARD_ZOOM_SELECTED :
                      DASH_IMAGE_ZOOM_NORMAL);
    }
}

static lv_obj_t *dash_selection_target_for_component(
  lvgl_app_page_home_view_t *view,
  lvgl_app_home_component_id_t component,
  lvgl_app_home_hotspot_t *hotspot)
{
  int card_index;

  if (view == NULL)
    {
      return NULL;
    }

  card_index = dash_left_card_index(component);
  if (card_index >= 0 &&
      card_index < (int)LVGL_APP_HOME_LEFT_CARD_COUNT &&
      view->left_card_images[card_index] != NULL)
    {
      return view->left_card_images[card_index];
    }

  return hotspot != NULL ? hotspot->obj : NULL;
}

static void dash_apply_selected_component(
  lvgl_app_page_home_view_t *view,
  lvgl_app_home_component_id_t component)
{
  lvgl_app_home_hotspot_t *selected = NULL;
  lv_obj_t *target;

  if (view == NULL)
    {
      return;
    }

  if (view->selected_component == component)
    {
      return;
    }

  selected = dash_find_hotspot(view, component);
  target = dash_selection_target_for_component(view, component, selected);
  view->selected_component = component;
  dash_update_left_card_feedback(view, component);
  dash_update_selection_box(view, target);
  dash_update_selection_label(view, selected != NULL ? selected->name : NULL);
  if (selected != NULL)
    {
      LVGL_APP_LOGI(HOME_VIEW_TAG, "feedback selected %s",
                    selected->name);
    }
}

