  aicfb_enable_clk(fbi, AICFB_ON);

  aicfb_update_alpha(fbi);

  aicfb_update_layer(fbi);

  /* Always enable panel and set power on */
  fbi->power_on = true;
  aicfb_enable_panel(fbi, AICFB_ON);

